import { merge } from 'lodash-es';

import { DEFAULT_DATATABLE_CONFIG } from '../DataTable/constants.js';
import type { DataTableProps } from '../DataTable/DataTable.js';
import type { TableVariantConfig } from '../types/shared-table-types.js';
import type {
  RequiredDataTableConfiguration,
  DataTableContextConfig,
} from '../types/table-config-types.js';

/**
 * Build DataTable configuration.
 *
 * @param props - config from props
 * @param contextConfig - config from context
 *
 * @returns RequiredDataTableConfiguration
 */
export function buildDataTableConfig(
  props: React.PropsWithChildren<DataTableProps>,
  contextConfig: DataTableContextConfig,
): RequiredDataTableConfiguration {
  const columnVisibility =
    props.columnVisibility ?? contextConfig.columnVisibility ?? {};
  const fullWidth =
    props.fullWidth ??
    contextConfig.fullWidth ??
    DEFAULT_DATATABLE_CONFIG.fullWidth;
  const lineWrap =
    props.lineWrap ??
    contextConfig.lineWrap ??
    DEFAULT_DATATABLE_CONFIG.lineWrap;
  const resizable =
    props.resizable ??
    contextConfig.resizable ??
    DEFAULT_DATATABLE_CONFIG.resizable;
  const sortable =
    props.sortable ??
    contextConfig.sortable ??
    DEFAULT_DATATABLE_CONFIG.sortable;
  const pagination =
    contextConfig.pagination ?? DEFAULT_DATATABLE_CONFIG.pagination;
  const selectableRows =
    props.selectableRows ??
    contextConfig.selectableRows ??
    DEFAULT_DATATABLE_CONFIG.selectableRows;
  const rowThresholds =
    props.rowThresholds ??
    contextConfig.rowThresholds ??
    DEFAULT_DATATABLE_CONFIG.rowThresholds;
  let variant =
    props.variant ?? contextConfig.variant ?? DEFAULT_DATATABLE_CONFIG.variant;
  variant = variant === 'default' ? variant : verifyVariant(variant);

  return {
    columnVisibility,
    selectableRows,
    fullWidth,
    lineWrap,
    resizable,
    sortable,
    pagination,
    variant,
    rowThresholds,
  };
}

/**
 * Get DataTable configuration merging the default ones with the stringify json config.
 * In case there is a conflict property, default would prevail.
 * In case there is any parse error. It will return an empty config.
 *
 * @param serializedConfig - stringify json config
 *
 * @returns - DataTableConfiguration
 */
export function deserializeConfig(
  serializedConfig: string,
): DataTableContextConfig {
  try {
    return merge({}, DEFAULT_DATATABLE_CONFIG, JSON.parse(serializedConfig));
  } catch (error) {
    return DEFAULT_DATATABLE_CONFIG;
  }
}

/**
 * Verifies if the known values of the variant are correct.
 * If not, assign the default values
 * @param variant - current table variant
 */
function verifyVariant(variant: TableVariantConfig): TableVariantConfig {
  // if rowDensity is not set to a valid value, then fall-back to default value.
  if (
    variant.rowDensity !== undefined &&
    !(
      variant.rowDensity === 'default' ||
      variant.rowDensity === 'comfortable' ||
      variant.rowDensity === 'condensed'
    )
  ) {
    // eslint-disable-next-line no-console
    console.warn(
      'rowDensity is not set to a valid value. Falling back to default value.',
    );
  }
  variant.rowDensity =
    variant.rowDensity === 'default' ||
    variant.rowDensity === 'comfortable' ||
    variant.rowDensity === 'condensed'
      ? variant.rowDensity
      : 'default';

  // if rowSeparation is not set to a valid value, then fall-back to default value.
  if (
    variant.rowSeparation !== undefined &&
    !(
      variant.rowSeparation === 'none' ||
      variant.rowSeparation === 'horizontalDividers' ||
      variant.rowSeparation === 'zebraStripes'
    )
  ) {
    // eslint-disable-next-line no-console
    console.warn(
      'rowSeparation is not set to a valid value. Falling back to default value.',
    );
  }
  variant.rowSeparation =
    variant.rowSeparation === 'none' ||
    variant.rowSeparation === 'horizontalDividers' ||
    variant.rowSeparation === 'zebraStripes'
      ? variant.rowSeparation
      : 'horizontalDividers';

  return variant;
}
